#!/usr/bin/env python3
"""Build buyer-only displays and briefs from the approved public catalogue."""
from pathlib import Path
from html import escape
import csv,json,re,shutil,subprocess
from buyer_information import dossier_html,dossier_brief,evaluation_sources_html
from pricing_publication import record as price_record,full_html as price_html,brief_prices,usd,pair,usd_number

ROOT=Path(__file__).resolve().parents[1]
HUB='https://thearchitect-max.github.io/MyProjects/'
def money(v):return 'EUR '+format(v,',')
def ul(items):return '<ul>'+''.join('<li>'+escape(s)+'</li>' for s in items)+'</ul>'
def main():
 subprocess.run(['node',str(ROOT/'tools/build_calculation_check.cjs')],check=True)
 d=json.loads((ROOT/'assets/buyer-catalogue.json').read_text());projects=d['projects'];cats={c['id']:c for c in d['categories']}
 dossiers=json.loads((ROOT/'assets/buyer-dossiers.json').read_text());dossier_by_ref={p['ref']:p for p in dossiers['projects']};evaluation_sources=json.loads((ROOT/'assets/evaluation-sources.json').read_text());applications=json.loads((ROOT/'assets/application-combinations.json').read_text())
 pricing=json.loads((ROOT/'assets/pricing-catalogue.json').read_text());assert len(projects)==len(pricing['projects'])==108
 header='<header class="site-header"><a class="wordmark" href="'+HUB+'"><span class="brand-mark" aria-hidden="true">TA</span><span>THEARCHITECT_MAX<span class="wordmark-sub">PRIVATE SOFTWARE IP</span></span></a><nav aria-label="Primary"><a class="hub-return button secondary compact" data-hub-return href="'+HUB+'">← Return to hub</a><a href="'+HUB+'displays/">Project displays</a><a href="'+HUB+'identities.html">Asset register</a><a href="'+HUB+'connections.html">Connections</a><a href="'+HUB+'musk.html">Strategic fit</a><a href="'+HUB+'valuation.html">Prices &amp; method</a><a href="'+HUB+'sources.html">Sources</a><a href="'+HUB+'acquisition.html">Acquisition</a></nav></header>'
 footer='<footer class="site-footer"><div><strong>THEARCHITECT_MAX</strong><p>Independent software assets. Individually scoped acquisition.</p></div><div><a href="'+HUB+'policy.html">Terms &amp; disclosure</a><p>© 2026 · First-party rights reserved.</p></div><a class="button secondary compact" data-hub-return href="'+HUB+'">← Return to hub</a></footer>'
 dialog='<dialog id="enquiry-dialog" aria-labelledby="enquiry-heading"><div class="dialog-head"><h2 id="enquiry-heading">Prepare an acquisition enquiry</h2><button class="icon-button" data-close-dialog aria-label="Close enquiry">×</button></div><p>This draft stays on your device. Send it through the verified seller contact channel supplied with this portfolio. Nothing is submitted here.</p><label for="enquiry-text">Enquiry draft</label><textarea id="enquiry-text" rows="13"></textarea><div class="dialog-actions"><button class="button" data-copy-enquiry>Copy draft</button><button class="button secondary" data-save-enquiry>Save draft</button></div><p class="small" id="enquiry-feedback" role="status" aria-live="polite"></p></dialog>'
 def shell(title,description,content,body='',canonical=None,root=False,identity=None):
  prefix='' if root else '../../';head='<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="'+escape(description,quote=True)+'"><title>'+escape(title)+' — THEARCHITECT_MAX</title><link rel="stylesheet" href="'+prefix+'assets/exhibition.css?v=showroom1"><link rel="stylesheet" href="'+prefix+'assets/buyer-showroom.css?v=seller8">'
  if identity:head+='<meta name="asset-reference" content="'+identity['ref']+'"><meta name="asset-alias" content="'+escape(identity['referenceName'],quote=True)+'"><meta name="asset-dossier" content="'+identity['profileUrl']+'">'
  if canonical:head+='<link rel="canonical" href="'+canonical+'">'
  h=header.replace('../../acquisition.html','acquisition.html') if root else header
  return '<!doctype html><html lang="en"><head>'+head+'</head><body'+body+'>'+h+'<main id="main">'+content+'</main>'+footer+dialog+'<script src="'+prefix+'assets/exhibition.js?v=seller6" defer></script><script src="/MyProjects/assets/audio-player.js?v=music3" defer></script></body></html>'
 mapping=[];cards=[];rows=[]
 for a in projects:
  ref=a['ref'];slug=a['slug'];c=cats[a['categoryId']];prices=price_record(a,pricing)['values'];folder=ROOT/'products'/slug;folder.mkdir(parents=True,exist_ok=True)
  actions='<div class="hero-actions"><button class="button" data-asset-enquiry data-alias="'+escape(a['referenceName'],quote=True)+'" data-profile="'+a['profileUrl']+'" data-display="'+a['displayUrl']+'" data-ref="'+ref+'" data-title="'+escape(a['title'],quote=True)+'" data-price="'+str(a['askingReferenceEUR'])+'">Discuss acquisition ↗</button><a class="button secondary" href="factsheet.pdf" download>Factsheet PDF ↓</a><a class="button secondary" data-project-profile href="'+a['profileUrl']+'">Asset dossier ↗</a></div>'
  hero='<section class="product-hero"><div class="hero-copy"><p class="eyebrow">'+ref+' / '+escape(a['referenceName'])+' / SELLER-OFFERED IP ASSET</p><h1>'+escape(a['title'])+'</h1><p class="hero-lede">'+escape(a['summary'])+'</p>'+actions+'</div><aside class="asset-plaque"><span class="plaque-id">'+ref+'</span><p>'+escape(c['title'])+'</p><div class="plaque-alias">'+escape(a['referenceName'])+'</div><span class="stage">'+escape(a['maturity'])+'</span><div class="plaque-price"><span>SELLER ASKING REFERENCE / AS IS</span><strong>'+money(a['askingReferenceEUR'])+'</strong><small class="price-usd" data-currency="USD">≈ '+usd(a['askingReferenceEUR'],pricing)+'</small><span class="restored-plaque-label">RECREATION COST ESTIMATE</span><strong class="restored-plaque-cost">'+money(prices['replacementCostEUR'])+'</strong><small class="price-usd" data-currency="USD">≈ '+usd(prices['replacementCostEUR'],pricing)+'</small><a class="price-source-short" href="#pricing">All prices &amp; sources →</a></div></aside></section>'
  breadcrumb='<div class="breadcrumb"><a href="'+HUB+'">Portfolio hub</a><span>/</span><a href="'+HUB+'displays/">Project displays</a><span>/</span><span>'+ref+' · '+escape(a['referenceName'])+'</span></div>'
  body=breadcrumb+hero+'<nav class="page-nav" aria-label="On this page"><a href="#product">Overview</a><a href="#buyer-fit">Buyer fit</a><a href="#functions">Functions &amp; outputs</a><a href="#scope">Current scope</a><a href="#acquire">Acquisition</a><a href="#product-dossier">Product dossier</a><a href="#pricing">Prices &amp; sources</a><a href="#buyer-information">Documents</a></nav><div class="product-content">'
  content=[('product','01','Product overview','<p class="lead-copy">'+escape(a['overview'])+'</p>'),('buyer-fit','02','Potential acquirers',ul(a['potentialBuyers'])+'<p>'+escape(a['summary'])+'</p>'),('functions','03','Functions & outputs','<h3>Documented functions</h3><div class="functions">'+''.join('<div class="function-row"><span>'+str(i+1).zfill(2)+'</span><p>'+escape(f)+'</p></div>' for i,f in enumerate(a['capabilities']))+'</div>'+'<h3>Available output types</h3>'+ul(a['outputTypes'])),('scope','04','Current offered position','<dl class="status-grid"><div><dt>Fixed identity</dt><dd>'+ref+' · '+escape(a['referenceName'])+'</dd></div><div><dt>Offered edition</dt><dd>'+escape(dossier_by_ref[ref]['version'])+'</dd></div><div><dt>Development stage</dt><dd>'+escape(a['maturity'])+'</dd></div><div><dt>Acquisition position</dt><dd>'+escape(a['availability'])+'</dd></div></dl><p>'+escape(a['maturityNote'])+'</p><div class="boundary-box"><h3>Material scope conditions</h3>'+ul(a['materialBoundaries'])+'</div>'),('acquire','05','Acquisition perimeter','<div class="economics-grid"><div><span>Seller asking reference</span><strong>'+money(a['askingReferenceEUR'])+'</strong><small>Indicative seller reference · EUR</small></div><div><span>Offered transaction</span><strong>AS IS</strong><small>Separate written agreement</small></div></div><p class="small">The asking reference is a seller choice, not an independent market appraisal. Final rights, delivery, acceptance and consideration are agreed separately.</p><div class="scope-columns"><div><h3>Offered first-party scope</h3>'+ul(a['offeredScope'])+'</div><div><h3>Separately scoped or excluded</h3>'+ul(a['excludedScope'])+'</div></div>'+actions),('buyer-information','08','Buyer information','<p>Review the concise factsheet or the product brief. Further technical, legal and commercial diligence is handled through an agreed review process.</p><div class="buyer-info-actions"><a class="button" href="factsheet.pdf" download>Factsheet PDF ↓</a><a class="button secondary" href="product-brief.md" download>Product brief ↓</a></div><p><a class="text-link" data-project-profile href="'+a['profileUrl']+'">View full asset profile ↗</a></p>')]
  content.insert(-1,('product-dossier','06','Product edition & qualification',dossier_html(a,dossier_by_ref[ref],applications)))
  content.insert(-1,('pricing','07','Prices &amp; sources',price_html(a,pricing)))
  for id_,num,title,text in content:body+='<section id="'+id_+'" class="split-section"><div><p class="eyebrow">'+num+' / '+title.upper()+'</p><h2>'+title+'</h2></div><div>'+text+'</div></section>'
  body+='</div>'
  (folder/'index.html').write_text(shell(a['title'],a['summary'],body,body=' data-project-ref="'+ref+'" data-project-slug="'+slug+'" style="--accent:#c5a46d"',canonical=a['displayUrl'],identity=a))
